/**
 * Icon set — Lucide, addressed by SEMANTIC name.
 *
 * ONE LIBRARY, TWO DELIVERY MECHANISMS, and they are not redundant. This file is the React
 * half: components, for the landing page. The other half is the `--sb-icon-*` custom
 * properties in src/css/sidebar-icons.scss, because sidebar rows and DocCard tiles are
 * decorated by CSS `mask-image` on a pseudo-element and a mask takes a data URI, not JSX.
 * Both halves are Lucide, both pinned to the same version. The CSS half and the vendored
 * SVGs under assets/icons/lucide/ are generated by scripts/site/generate-icons.mjs; this
 * file is hand-written, because re-exporting nine components needs no generator.
 *
 * WHY SEMANTIC NAMES AND NOT LUCIDE'S. Call sites say what the icon MEANS — <Icon name="Fleet" />
 * — never what it depicts. That indirection has now paid for itself twice in one week: the set
 * moved from SF Symbols to Lucide on 2026-08-16 and not one call site changed. Keep it. If you
 * find yourself importing `Stethoscope` directly in a page, add a semantic alias here instead.
 *
 * SUPERSEDES the vendored SF Symbols set (nine glyphs extracted into this file as raw JSX by
 * scripts/site/extract-icons.py, now deleted). Two reasons, and the second is the load-bearing
 * one:
 *   1. LICENCE. Lucide is ISC — an OSI-approved permissive licence that plainly allows
 *      redistribution in a commercial product. SF Symbols glyph artwork is Apple's, licensed
 *      for use in software on Apple platforms; a Zebra documentation site is not that, and no
 *      amount of care in the wrapper code changes what the artwork is.
 *   2. FIT. The site's 34 sidebar glyphs were already drawn in the Lucide idiom — 24x24, one
 *      uniform stroke, round caps. SF Symbols are FILLED glyphs on Apple's optical grid with
 *      non-square viewBoxes, so they cannot hold a consistent weight beside them. Several had
 *      no honest equivalent at all: `sitemap` matched five different SF glyphs and none of
 *      them was a sitemap, `filter` mapped to a "decrease lines" mark rather than a funnel,
 *      and the closest match for `compass` was SFSafari — Apple's browser logo.
 */
import React from 'react';
import {
  Nfc,
  Settings,
  Network,
  Plug,
  ShieldCheck,
  Play,
  Wrench,
  SlidersHorizontal,
  Activity,
  Lightbulb,
  Newspaper,
  Video,
  Globe,
  Stethoscope,
  CircleHelp,
  BookA,
  ArrowUpRight,
  ChevronRight,
  ChevronLeft,
  ChevronDown,
  Route,
  Braces,
  RadioTower,
  LibraryBig,
  List,
  Paperclip,
  History,
  Headset,
  PanelLeft,
  PanelLeftClose,
  Equal,
  Check,
  X,
  Copy as CopyGlyph,
  Mail,
  Book,
  Layers,
  Compass,
  Users,
  Clock,
  Timer,
  Target,
  Link as LinkGlyph,
  Milestone,
  ListChecks,
  Flag,
  Info,
  type LucideIcon,
} from 'lucide-react';

/**
 * The semantic vocabulary. Left column is what a call site says; right is what Lucide draws.
 * Add a row rather than importing a Lucide component anywhere else — and add the same icon to
 * REACT_ICONS in scripts/site/generate-icons.mjs so its SVG is vendored with the rest.
 */
export const SYMBOLS = {
  /** A tag read over the air. `nfc` is the contactless-radio mark; `scan-barcode` was the
   *  other candidate and was rejected because the RFID surface is the subject here, and the
   *  barcode scanner is a secondary capability of the sled. */
  Inventory: Nfc,
  /** Device configuration: identity, runtime, regulatory, Wi-Fi, endpoints, certificates. */
  Reader: Settings,
  /** Many readers against one broker — reads as both fleet scale and MQTT topology. */
  Fleet: Network,

  /* ── The six "popular" row marks, one per ROW rather than one per group ──────────────
   * Guide=list-checks and Reference=braces used to cover these: every how-to row drew the
   * checklist and every reference row drew the braces, so within a column all three rows
   * looked identical and the icon carried no information the column heading did not already
   * give. Both are WITHDRAWN below — index.tsx:384 and :406 were their only two call sites in
   * the repo. Re-add either if a surface ever wants a generic "a how-to" or "an API page"
   * mark; nothing else referenced them.
   *
   * THESE NOW DRAW AT 24px IN currentColor, and that is a CHANGED PREMISE, not a detail.
   * They were picked on 2026-08-20 at the 16px and --lp-faint that `.rowIcon` then imposed,
   * and this note used to end "if .rowIcon is ever raised to 20px, both are worth
   * revisiting". Later the same day it was raised to 1.5rem to match docs.dyte.io, so that
   * condition fired and the two rejects were re-examined:
   *   - file-badge (a document with a seal) lost to shield-check ONLY because its seal is a
   *     ~3px detail at 16px. At 24px it is legible and it is arguably the more literal mark
   *     for a certificate FILE. shield-check keeps the row anyway, on the reason that never
   *     depended on size: it is the 🛡️ the API reference already puts on Certificate
   *     Management, so the two surfaces agree.
   *   - circle-play lost to play partly on the ring failing at 16px, but also because that
   *     ring is the same r=10 outline as Faq and RestApi below — a confusability argument
   *     that holds at any size. play also matches the page's own ⏯️ frontmatter.
   * Both picks therefore survive on grounds independent of the size, which is why the size
   * change moved neither. Do not read the list below as still owing a re-check.
   *
   * Where a mark already exists elsewhere in this ONE icon system, these agree with it, so a
   * concept draws the same glyph on the landing row, the sidebar header and the DocCard tile:
   * the emoji map in src/css/cards.scss sends 🔌 to plug, ⏯️/▶️ to play, 🛠️ to wrench,
   * 🎛️ to sliders and 🌐 to globe, and sidebars/api-mqtt.ts gives the Control category
   * `sidebar-icon--sliders`, which REGISTRY resolves to sliders-horizontal. */

  /** A named, addressable MQTT connection point — the thing config_endpoint operates on.
   *  A plug IS a connection point; the page's own reference section carries 🔌. Not a
   *  topology mark: circles-and-edges would collide with Fleet above. */
  Endpoint: Plug,
  /** TLS material on the reader — install, list, delete, rotate. A shield-and-tick, because
   *  the certificate ARTEFACT marks (file-badge, file-key) hang their whole meaning on a
   *  ~3px detail in the lower-left corner of a page outline and lose it at 16px, leaving a
   *  generic "a file". This also matches the 🛡️ the API reference puts on Certificate
   *  Management. */
  Certificate: ShieldCheck,
  /** START / STOP a run — control_operation flipping the radio between IDLE and ACTIVE.
   *  Bare triangle, not circle-play: the ring is the same r=10 outline as Faq below and as
   *  RestApi, and at 16px the enclosed triangle stops resolving. */
  Operation: Play,
  /** The reader's ADMINISTRATION surface: status, version, region, network, endpoints,
   *  certificates, event config, OS update, reboot. Named Administer and not Manage because
   *  Reader above already means "device configuration" and lists the same nouns — the two
   *  would be indistinguishable as vocabulary even though the glyphs differ. */
  Administer: Wrench,
  /** The control plane: operating mode, Gen2 query, post-read filters — several independent
   *  parameters each at its own setting, which is what the three offset handles draw.
   *  MUST be SlidersHorizontal by its full name: lucide-react 1.31.0 re-exports
   *  `SlidersVertical as Sliders`, so importing `Sliders` silently draws the vertical
   *  faders instead. Verified: Sliders === SlidersVertical is true. */
  Control: SlidersHorizontal,
  /** The EVENT plane: heartBeatEVT, alerts and mqttConnEVT — messages the reader emits
   *  UNPROMPTED, as opposed to the two surfaces above, which are things you send it.
   *
   *  THE GLYPH IS CARRYING THE DIRECTION OF TRAFFIC, and that is the whole reason for this
   *  pick rather than a prettier one. On the landing page's reference list this mark sits
   *  directly under `Administer: Wrench` and `Control: SlidersHorizontal`, and both of those
   *  are HAND-ON-THE-MACHINE marks: a tool you pick up, a fader you push. A pulse trace is a
   *  READOUT — something arriving on its own that you watch. The three glyphs therefore say
   *  "you act, you act, it reports" before a word is read, which is the single most useful
   *  thing that list can tell someone scanning it.
   *  It also happens to enumerate its own contents: the trace IS the heartbeat, the spike IS
   *  an alert, and a trace that stops IS the disconnect.
   *
   *  Rejected: `Bell` / `BellRing` — a bell is a NOTIFICATION, something a UI shows a person;
   *  these are wire messages a broker delivers to a subscriber, and the bell would also
   *  narrow the mark to `alerts`, one of the three. `Radio` / `Rss` — `MqttApi: RadioTower`
   *  already owns the transmission idea for this site, and `Rss` is separately rejected in
   *  that entry for reading first as "blog feed". `Zap` — reads as speed or as a trigger you
   *  fire, and firing is the opposite direction. `HeartPulse` — `Diagnose: Stethoscope` owns
   *  the medical register here, and it would narrow the mark to heartBeatEVT. `Megaphone` —
   *  announcement, which is marketing's word, not a protocol's. `Waves` — a signal with no
   *  events in it; nothing distinguishes it from noise. */
  Events: Activity,

  /* ── The three RESOURCE KINDS, added 2026-08-29 for the landing page's resource
   * covers. One glyph per content type, drawn white on the accent at 36px, so the
   * legibility floor these are chosen against is 36px — the most forgiving in this
   * file. They are picked to be distinguishable from EACH OTHER at a glance in a
   * three-across grid, which is a different test from the rest of the set: these three
   * are always seen together. */

  /** An EXPLANATION — the Diátaxis kind, not a task. The three cards it draws are all
   *  core-concepts pages: how commands flow, how the radio reads tags, how the security
   *  model works. A lamp is the near-universal mark for "here is the idea".
   *
   *  Rejected: `BookOpen` — the collision this file already records against
   *  `Glossary: BookA`, and it says "documentation" generally where every card on this
   *  page is documentation. `Route` — taken by `Guides`, and a route is a SEQUENCE of
   *  steps, which is the how-to kind, i.e. the opposite Diátaxis quadrant from these
   *  pages. `GraduationCap` — rejected in the Guides entry for implying a course, and it
   *  implies one here too. `FileText` — a file, not an idea; it would be the same mark
   *  whatever the page said. `Compass` — orientation, and "Get Oriented" is a different
   *  section of this site.
   *  ACCEPTED RISK, stated because it is real: in documentation a lamp often means a
   *  TIP callout. Nothing on this site uses it that way — the admonitions are emoji-led
   *  and the icon set has no tip glyph — so the association is free here. If a tip
   *  callout ever takes a lamp, one of the two has to move. */
  Explanation: Lightbulb,

  /** A BLOG POST. A folded paper is the article mark, and it carries the one thing that
   *  matters on this row: these are EDITORIAL pieces from zebra.com, not documentation.
   *
   *  Rejected: `Rss` — mechanically the blog mark and rejected twice already in this
   *  file, once for `MqttApi` where its "blog feed" reading was wrong; here that reading
   *  would be right, but it means SUBSCRIBE, and these cards link to single posts.
   *  `PenLine` / `Feather` — authoring, i.e. the act of writing rather than the thing
   *  written. `FileText` — held for nothing, and indistinguishable from `Explanation`'s
   *  rejected candidate at any size. */
  Blog: Newspaper,

  /** A VIDEO — the DevCon session recordings.
   *
   *  Rejected: `Play` — TAKEN, by `Operation: Play`, where it means "start the RFID
   *  radio"; one glyph meaning both "run a command" and "watch a talk" is exactly the
   *  collision this file exists to prevent. `CirclePlay` — WITHDRAWN from this file
   *  earlier on legibility at 16px; it would clear the 36px floor here, but re-adding a
   *  withdrawn glyph for one surface splits its record across two decisions.
   *  `MonitorPlay` — a screen showing a video is two ideas where one will do.
   *  `Youtube` — a vendor logo, and these are hosted on Zebra's own developer portal. */
  Video: Video,

  /** The HTTP surface — the FXR60 / FXR90 fixed-reader line, read out of a vendor OpenAPI
   *  document, as opposed to everything else here which is MQTT on handheld sleds. It does
   *  restate what the row's own REST chip says; accepted, because every non-transport
   *  alternative rhymed with a glyph already on this page (route with Fleet, book-* with
   *  Glossary, braces/file-braces with the withdrawn Reference). */
  RestApi: Globe,

  /** Symptom-first diagnosis. */
  Diagnose: Stethoscope,
  /** Frequently asked questions. */
  Faq: CircleHelp,
  /** A dictionary of terms. */
  Glossary: BookA,
  /** Open / expand affordance. */
  ArrowOut: ArrowUpRight,
  /** "This row goes somewhere" — the disclosure chevron parked at the right end of a
   *  .row, transparent until the row is hovered or focused.
   *
   *  IT USED TO SHARE ITS COMPONENT WITH SidebarToggle, and the fact that it no longer does is
   *  the argument for this indirection rather than against it. Both were `chevron-right` until
   *  2026-08-30; SidebarToggle then moved to `chevrons-right`, the DOUBLE chevron, and this
   *  entry did not have to move with it. Had the two been folded into one name because they
   *  happened to be drawn alike, that change would have silently redrawn every row disclosure
   *  in the site. Two semantic names for one glyph is what makes them separable later.
   *
   *  'chevron-right' is therefore now in REACT_ICONS on this entry's account alone. */
  Advance: ChevronRight,
  /** The reverse of Advance, for the resource-carousel pager's "previous page" control
   *  (index.tsx MediaCarousel) — the only other place a chevron states a direction rather
   *  than naming a thing. Same reasoning as Advance applies in the other direction: this
   *  glyph means "go back one page" and nothing else, so it gets its own semantic name
   *  rather than a `rotate: 180deg` on Advance, which would carry the ambiguity into
   *  whichever future control reads the rotated version. Adds 'chevron-left' to
   *  generate-icons.mjs's REACT_ICONS, vendored alongside chevron-right. */
  Back: ChevronLeft,
  /** The open/closed caret on a navbar menu trigger — the mark that ROTATES to state
   *  which of the two the control is in, not one that points anywhere. Added 2026-08-28
   *  with the navbar NavigationMenu work; drawn at 15x15 inside the trigger by
   *  src/theme/NavbarItem/DropdownNavbarItem/Desktop, rotated -180deg by
   *  src/css/navbar-menu.scss when the menu opens.
   *
   *  ITS OWN NAME, NOT `Advance` ROTATED, for exactly the reason `Back` gives above:
   *  `Advance` means "this row goes somewhere" and a disclosure caret means "this control
   *  is open or shut". One glyph carrying both would make a future change to either one
   *  silently move the other, and these two can render on the same screen — the caret is
   *  in the navbar and `Advance` is on the landing rows below it.
   *
   *  THE REFERENCE'S GLYPH IS NOT THIS ONE, and the substitution is deliberate: Radix
   *  Primitives draws its CaretDown as a FILLED path on a 15x15 grid, and adopting it
   *  would put a second icon library on the site, which the header of this file forbids.
   *  Lucide's chevron-down is the same downward chevron as a 1.8px stroke, so it reads a
   *  shade lighter at the same box. Adds 'chevron-down' to generate-icons.mjs's
   *  REACT_ICONS; the SVG was already vendored (the folder is in LIBRARY state), so the
   *  entry is there to survive a future `npm run icons:prune`. */
  Disclosure: ChevronDown,
  /* ── The dual-trigger sidebar toggle, added 2026-09-02 ─────────────────────────────────
   *  Replaces the single chevron-based collapse chip (history above, now removed with it) with
   *  two triggers reading three marks between them:
   *    - Trigger A, inside the sidebar's own header, visible only while expanded: `PanelLeft`
   *      at rest, swapping to `PanelLeftClose` on hover/focus/active — the same "hover previews
   *      the action" pattern play/pause icons use, not a rotation. A panel does not reverse its
   *      meaning when rotated the way a chevron does (037's own finding, still true), which is
   *      exactly why this pair needs two distinct marks rather than one transformed.
   *    - Trigger B, persistent in the top navbar: `Equal`, unrotated in both states, because it
   *      is not depicting a direction at all — three bars read as "menu/panel control" on sight
   *      regardless of which way the panel currently sits, which is the point of a control that
   *      has to make sense whether the sidebar is open or shut.
   *  `SidebarToggle` is reused as a name rather than retired: the semantic role — "the control
   *  that toggles the sidebar" — is unchanged even though the glyph and the component consuming
   *  it both changed under it. */
  SidebarPanel: PanelLeft,
  SidebarPanelClose: PanelLeftClose,
  SidebarToggle: Equal,

  /* ── The five navigation LABELS, added 2026-08-23 ────────────────────────────────────
   * Picked in .ai-history/037-sidebar-icons.md, which names the rejected candidates and the
   * reason for each rejection, to the standard the rest of this file holds. The count is FOUR,
   * not five: `REST API` already has a glyph — `RestApi: Globe` above — and re-picking it would
   * fork one concept across two marks.
   *
   * These draw at 20px (the sidebar chip) and 24px (a landing row), so the legibility floor is
   * 20px, which is more forgiving than the 16px that withdrew `file-badge` and `circle-play`.
   * One pick below depends on that. */

  /** The ten task-oriented guide categories. Every one is a SEQUENCE OF STEPS toward an
   *  outcome, which is what a route is.
   *
   *  Rejected: `BookOpen` — collides with `Glossary: BookA` above; at 20px the difference is a
   *  letter on a cover versus an open spread. `Compass` — "Get Oriented" is a CHILD of Guides
   *  and is orientation itself, so the parent and one of its ten children would be the same
   *  idea. `ListChecks` — already withdrawn from this file, for carrying no information the
   *  column heading did not give. `GraduationCap` — implies a course with completion; these are
   *  reference how-tos. `Map` — a map is the territory, a route is the path through it, and
   *  "Choose your path" is literally one of the pages. */
  Guides: Route,

  /** The API Reference section as a whole.
   *
   *  THIS PICK IS PRE-AUTHORISED BY THIS FILE. `Reference = Braces` was WITHDRAWN above, not
   *  rejected, and its note reads: "Re-add either if a surface ever wants a generic 'an API
   *  page' mark." The withdrawal was about SCOPE — as a PER-ROW mark every reference row drew
   *  the same braces and said nothing. As a CATEGORY mark, drawn once for the whole section,
   *  being generic is exactly the job.
   *
   *  `{}` is also the strongest agreement argument in the set: it is the near-universal mark for
   *  a JSON API, and this reference is JSON over MQTT and JSON over REST.
   *
   *  Rejected: `Code` / `FileCode` — mean SOURCE CODE; this documents a wire protocol you call.
   *  `Terminal` — nothing here is a CLI. `Brackets` — `[]` against `{}` at 20px is two pairs of
   *  thin strokes, and braces carry the JSON association that brackets do not. */
  ApiReference: Braces,

  /** The MQTT surface. Publish/subscribe through a broker: one publisher, many subscribers,
   *  mediated. A transmitting mast is that shape, and it PAIRS with its sibling — `RestApi` is
   *  a globe, so the two protocols get a sphere and a mast, unmistakable at a glance in a
   *  two-item dropdown.
   *
   *  Rejected: `Network` / `Waypoints` / `Share2` — `Fleet: Network` above is chosen PARTLY
   *  because it "reads as both fleet scale and MQTT topology", so a nodes-and-edges glyph here
   *  would be the same idea twice. `Nfc` — taken by `Inventory`. `Rss` — mechanically the
   *  pub/sub mark, but its first reading is "blog feed", and a glyph whose first reading is
   *  wrong is a bad glyph. `MessageSquare` — a speech bubble reads as chat between people;
   *  these are machine telemetry. `Antenna` / `Radio` — both receivers, and a broker's defining
   *  behaviour is DISTRIBUTION. */
  MqttApi: RadioTower,

  /** Six heterogeneous children: Glossary, FAQs, Quick Reference, Additional Reference, Release
   *  Notes, Support. The only honest description is A SHELF OF REFERENCE MATERIAL.
   *
   *  THE COLLISION HAS TO BE ARGUED, NOT WAVED PAST. `Glossary: BookA` is a book and Glossary is
   *  a child of Resources — the same parent/child trap that rejected `Compass` for Guides. It
   *  survives on SILHOUETTE: `BookA` is one closed book, wider than tall, with a letter on the
   *  cover; `LibraryBig` is three vertical spines, taller than wide. At 20px those are different
   *  SHAPES, not different details, unlike the 3px seal that withdrew `file-badge`.
   *
   *  THIS IS THE PICK THAT DEPENDS ON THE 20px FLOOR. At 16px, re-open it.
   *
   *  Rejected: `LifeBuoy` — Support is one of six children; naming the parent after one child
   *  misdescribes the other five. `Archive` — a storage box reads as SUPERSEDED, and Release
   *  Notes and Support are current. `FolderOpen` — honest but empty. `Bookmark` — a saved item,
   *  singular. `Layers` — stacked planes read as architecture or z-order, not documents. */
  Resources: LibraryBig,

  /* ── The six Resources CHILDREN ──────────────────────────────────────────────────────
   * .ai-history/037-sidebar-icons.md section 7. `Glossary` and `Faq` above already covered two of
   * the six and are unchanged; these are the other four.
   *
   * THIS SET WAS PICKED AS A COLUMN, NOT AS SIX INDEPENDENT ROWS, which is a different exercise
   * from every pick above it: all seven marks (the parent plus six children) render together in one
   * sidebar, so the binding test is whether any two are confusable at 20px in the same glance. Two
   * obvious candidates failed it on geometry that their names would have hidden, and both are worth
   * carrying here because they constrain whatever is added next:
   *
   *   `Table` for Quick Reference is `rect 18x18 rx=2` + one vertical + two horizontals.
   *   `PanelLeft` — SidebarToggle until 2026-08-30, when the collapse control went back to a
   *   double chevron — is `rect 18x18 rx=2` + one vertical. Table WAS the trigger glyph plus two
   *   lines, rendered a few pixels from it whenever the sidebar was open. The clash is gone with
   *   the glyph, and the finding is kept because it is about `Table`, which is still a candidate.
   *
   *   `LifeBuoy` for Support is `<circle r=10>` + spokes + `<circle r=4>`: the IDENTICAL closed
   *   r=10 outline as `Faq`'s CircleHelp, three rows above it in the same column. That is the
   *   `circle-play` argument this file already uses, verbatim.
   *
   * The card map in src/css/cards.scss sends BOTH the FAQs emoji and the Support emoji to one mark.
   * That is fine for cards, which appear singly with a visible title; it is why the nav must not. */

  /** Five children, every one a table of values you look up rather than read: the REST-to-MQTT
   *  mapping, RF profiles, factory defaults, limits, ports. Also the agreement pick — the row
   *  already carries a clipboard emoji, which cards.scss maps to this same `list`.
   *
   *  Rejected: `Table` and `Table2` and `TableProperties` — see the trigger collision above.
   *  `Gauge` — a third closed ring, and "at a glance" describes one child of five. `SquareStack` —
   *  stacked squares against `Layers`' stacked planes. `ClipboardList` — a clipboard reads as tasks
   *  to complete. `Zap` — `bolt` is Quick Start; "quick" is a coincidence of wording.
   *
   *  NOTE the one reuse: `sidebar-icon--list` is also on `Migrate an Existing Deployment` in the
   *  guides sidebar. Two sidebars, never rendered together, so no glance holds both — stated rather
   *  than exempted. */
  QuickReference: List,

  /** "Additional" is the whole meaning: matter ATTACHED to the reference rather than part of its
   *  main line — hardware matrix, regulatory, firmware compatibility, EPC standards, tools,
   *  versioning policy. A paperclip is the object that does that, and it is the object already on
   *  the row (its emoji is a paperclip), which makes this agreement with the THING rather than with
   *  a compressed category.
   *
   *  Rejected: `Book` — what cards.scss actually maps that emoji to, and it would be a third book
   *  beside `Glossary: BookA` and `Resources: LibraryBig` in one column. `FileStack` — the runner-up;
   *  honest as "more documents" but silent on the one thing that distinguishes this row, that they
   *  are SUPPORTING. `Link` — two interlocking hooks against the paperclip's single continuous loop,
   *  closer than it looks at 20px, and `link` is a live card mark so both can share a screen.
   *  `Archive` — reads as superseded; these pages are current. `Bookmark` — one saved item. */
  AdditionalReference: Paperclip,

  /** Three children: latest, history, deprecations-and-breaking-changes. The subject is VERSIONS
   *  OVER TIME, and one of the three is literally called history.
   *
   *  THE CIRCLE OBJECTION IS ANSWERED ON GEOMETRY, because this file's own method raises it —
   *  `Faq` is a sibling and `circle-play` was withdrawn for sharing its ring:
   *      circle-help   <circle cx=12 cy=12 r=10 />        a CLOSED ring
   *      history       M3 12a9 9 0 1 0 9-9 … L3 8         an OPEN arc, broken at 9 o'clock
   *                    M3 3v5h5                            an L-tick OUTSIDE the arc
   *  A closed ring against an open arc with an external corner tick is a SHAPE difference, which is
   *  the standard that admitted `LibraryBig` beside `BookA` — not a detail difference like the 3px
   *  seal that withdrew `file-badge`. At 16px the 1.5px break in the arc would close up visually and
   *  the two would become two rings, so this pick carries the same 16px caution `LibraryBig` does.
   *
   *  Rejected: `Clock` — what the card map gives, but plain time says nothing about versions.
   *  `Tags` — versions-as-tags is good reasoning, but `tag` is the card-map target for four emoji
   *  and is already a row in another sidebar, so `tags` would sit one overlapping shape from a mark
   *  that can render beside it. `FileClock` — a small clock badge on a page, the exact legibility
   *  failure that withdrew `file-badge`. `Megaphone` — an announcement, in a marketing register;
   *  this section is baselines and deprecations. `Milestone` — a signpost reads forward, as a
   *  roadmap; this documents the past. `ScrollText` — first reading is terms and conditions. */
  ReleaseNotes: History,

  /** Six children that escalate: self-serve, collect evidence, known issues, report a bug, scope
   *  policy, community. One is literally "collect evidence BEFORE CONTACTING SUPPORT" — a support
   *  desk is what that describes, and a headset is its universal mark. Its silhouette (a headband
   *  arc with two filled earcups, wide and low) shares nothing with any sibling.
   *
   *  Rejected: `LifeBuoy` — the identical closed r=10 ring as `Faq`, see the note above; that the
   *  card map already conflates the two emoji is corroboration, not a defence.
   *  `MessageCircleQuestion` — another ring AND another question mark, duplicating FAQs on both
   *  axes. `Ticket` / `Bug` — each names one child of six, which is the ground section 6 used to
   *  reject `LifeBuoy` for the parent. `Wrench` — taken twice, by `Administer` and by
   *  `Diagnose and Recover`. `Handshake` — partnership, not assistance. `Mail` — one channel, and
   *  this section's first instruction is not to use it yet. `Users` — a live card mark, and it means
   *  people in general.
   *
   *  CAVEAT, stated rather than buried: a headset implies humans at the end of the line. That is
   *  accurate while "contacting support" is a child page. If this section ever becomes self-serve
   *  only, the glyph over-promises and should be revisited. */
  Support: Headset,

  /* ── The two RECOVERY SURFACES' marks, added 2026-09-10 ───────────────────────────────
   * /404/ and /report-broken-link/ were the last two pages on the site still drawing their
   * marks as TEXT — a `content: '▸'` bullet in each stylesheet, and ✓ / ✗ / 📋 / 📧 baked
   * into button labels in report-broken-link.tsx. Emoji in a label is not an icon system: it
   * renders in the platform's colour font at the platform's size, so those four glyphs were
   * four different weights and two different colour models sitting inside buttons whose every
   * other property this design system controls. The four names below put them on the same
   * 1.8px Lucide stroke as the rest of the site.
   *
   * NO NEW NAME FOR THE TWO `▸` BULLETS: both mean "this row goes somewhere", which is what
   * `Advance` above already says, and both are the same disclosure-at-the-end-of-a-row
   * situation its note describes. Reusing it is the indirection working as designed. */

  /** The clipboard write SUCCEEDED — the transient label on report-broken-link's primary
   *  button, and the one place on the site that has to say "it worked" without relying on a
   *  colour the reader might not be able to see. A bare tick, not `CircleCheck`: the ring is
   *  the same r=10 outline this file rejects for `Operation` and `Faq`, and at the 16px this
   *  draws inside a button label it would close up. */
  Confirmed: Check,
  /** The clipboard write FAILED and the reader must select the text by hand. Lucide's `x` is
   *  the multiplication cross, which is the same mark the ✗ it replaces drew — the
   *  substitution changes the weight and the colour model, not the meaning. Not `CircleX` /
   *  `TriangleAlert`: this is an inline state on a button, not an admonition, and the site's
   *  admonition set owns the warning register. */
  Failed: X,
  /** COPY THIS TEXT — the Copy button on every code block, schema panel and the
   *  report-broken-link page.
   *  `copy` AND NOT `clipboard`, corrected 2026-09-10 at the owner's instruction. The two are
   *  different marks for different acts: a clipboard is a SURFACE you put things on, and copy
   *  is the two overlapping sheets that mean "duplicate this". Lucide draws both; the button
   *  says "Copy", so it takes the one named after what it does. (Not `ClipboardCopy` either —
   *  the small arrow inside its board is a ~3px detail at 16px, the same legibility floor that
   *  decided `Certificate` against `file-badge` further up this file.) */
  Copy: CopyGlyph,
  /** COMPOSE AN EMAIL — report-broken-link's secondary action, a `mailto:` link. An envelope,
   *  which is the universal mark and the one the 📧 it replaces already drew. Note that
   *  `Support: Headset` above rejects `Mail` for the support SECTION, on the grounds that mail
   *  is one channel among several; here the control IS the mail channel and nothing else, so
   *  the envelope is exact rather than reductive. */
  Email: Mail,

  /* ── THE PAGE-META LINE'S MARKS, moved into this file 2026-09-10 ──────────────────────
   * src/components/PageMeta used to carry these as INLINE <path> data copied out of the
   * vendored SVGs, on the reasoning that thirteen glyphs used once each did not justify an
   * import. The owner's report retired that reasoning: "the clock icon used in our docs isn't
   * the one you presented — use Lucide's clock icon from our pre-installed library". The paths
   * were in fact byte-identical to lucide-static's, but that is not something a reader of the
   * component can verify, and it is not something anything CHECKS — a hand-copied path is a
   * silent fork the moment Lucide redraws a glyph. Naming them here makes the component render
   * the same components the rest of the site does, and puts them under this file's one rule.
   *
   * THE FOUR DIÁTAXIS MARKS FIRST. These are the chip glyphs, one per document kind, and they
   * are the pairing the M1 mockup shows. Each is a NEW semantic name rather than a reuse:
   * `Explanation: Lightbulb` already exists above and means "here is the idea" on a resource
   * cover, which is a different job from "this page is of the explanation kind". */
  /** The EXPLANATION chip. An open book — reading rather than doing. Not `Lightbulb`, which
   *  this file already spends on the resource covers; two marks for one word is better than
   *  one mark for two meanings, which is the whole argument of the header. */
  DocExplanation: Book,
  /** The HOW-TO chip. The same three faders `Control` uses, and deliberately: a how-to is a
   *  page about operating something, which is exactly what that glyph says elsewhere. */
  DocHowTo: SlidersHorizontal,
  /** The REFERENCE chip. Stacked planes — a body of material you look INTO, not through. */
  DocReference: Layers,
  /** The TUTORIAL chip. A compass: a guided route with a bearing, which is what separates a
   *  tutorial from a how-to. `Guides: Route` above is the section mark and stays distinct. */
  DocTutorial: Compass,

  /* ── The nine pair marks. Each stands IN PLACE OF a label the line no longer prints —
   * see PageMeta's MARKS table for why the words moved to the accessibility tree. */
  /** Audience — who the page is written for. */
  MetaAudience: Users,
  /** Read time. A clock: elapsed time you spend reading. */
  MetaReadTime: Clock,
  /** Hands-on time. A STOPWATCH, not the clock above, and the distinction is the one the
   *  front-matter survey found the authors making: a tutorial's "Time: 15 min" is time spent
   *  DOING, an explanation's "Read time: 2 min" is time spent reading. Two labels the writers
   *  kept apart get two marks. */
  MetaTime: Timer,
  /** Use — what the page is for, i.e. what you are aiming at when you open it. */
  MetaUse: Target,
  /** Ties to — a cross-reference to another page, which is what a chain draws. */
  MetaTiesTo: LinkGlyph,
  /** Phase — a marker planted at a point along a route. */
  MetaPhase: Milestone,
  /** Prerequisite — things that must already be true, i.e. a checklist. */
  MetaPrerequisite: ListChecks,
  /** Goal — what you will have done by the end. */
  MetaGoal: Flag,
  /** The fallback for a label with no mark of its own, so an unmapped pair still renders a
   *  glyph rather than a ragged line. The label is in the DOM either way, so it still says
   *  what it is to anything that reads the page rather than looks at it. */
  MetaOther: Info,
} as const satisfies Record<string, LucideIcon>;

export type IconName = keyof typeof SYMBOLS;

/**
 * `Omit<…, 'name'>` is required, not tidiness. `React.SVGProps<SVGSVGElement>` already declares
 * `name?: string` (the SVG/HTML attribute), so extending it plainly leaves `name` widened to
 * `string` and every call site loses the union check — `<Icon name="Typo" />` would compile.
 * Removing it first makes our `name: IconName` the only declaration.
 */
export interface IconProps extends Omit<React.SVGProps<SVGSVGElement>, 'name'> {
  name: IconName;
  /** Edge length in px. Lucide draws on a 24x24 grid, so this is also the viewBox scale. */
  size?: number;
}

/**
 * `strokeWidth` defaults to 1.8, not Lucide's 2, to match the sidebar masks — the two sets
 * appear on the same screen and a half-pixel difference in weight reads as sloppiness. It is
 * a prop, so a call site that needs a heavier mark can still ask for one.
 *
 * `aria-hidden` by default: every current call site pairs the icon with a visible text label,
 * so announcing it would make a screen reader say the same thing twice. Pass `aria-hidden={false}`
 * and an `aria-label` for an icon that is the only content of a control.
 */
export function Icon({ name, size = 20, strokeWidth = 1.8, ...rest }: IconProps): React.ReactElement {
  const Glyph = SYMBOLS[name];
  return <Glyph size={size} strokeWidth={strokeWidth} aria-hidden focusable={false} {...rest} />;
}

export default Icon;
